/// <summary>Purpose-specific customer consent that is authoritative for recognition eligibility.</summary>
public sealed class CustomerRecognitionConsent
{
    private CustomerRecognitionConsent(){}
    private CustomerRecognitionConsent(long tenantId,long customerId,RecognitionConsentType consentType,string purpose,DateTime grantedUtc,DateTime?expiresUtc,string consentVersion,long capturedByUserId,string?evidenceReference)
    {ArgumentOutOfRangeException.ThrowIfNegativeOrZero(tenantId);ArgumentOutOfRangeException.ThrowIfNegativeOrZero(customerId);ArgumentOutOfRangeException.ThrowIfNegativeOrZero(capturedByUserId);if(!Enum.IsDefined(consentType))throw new ArgumentOutOfRangeException(nameof(consentType));TenantId=tenantId;CustomerId=customerId;ConsentType=consentType;Purpose=Required(purpose,200);GrantedUtc=Utc(grantedUtc);if(expiresUtc.HasValue&&Utc(expiresUtc.Value)<=GrantedUtc)throw new ArgumentOutOfRangeException(nameof(expiresUtc));ExpiresUtc=expiresUtc;ConsentVersion=Required(consentVersion,50);CapturedByUserId=capturedByUserId;EvidenceReference=Optional(evidenceReference,500);CreatedUtc=GrantedUtc;}
    public long Id{get;private set;}public long TenantId{get;private set;}public long CustomerId{get;private set;}public RecognitionConsentType ConsentType{get;private set;}public string Purpose{get;private set;}=string.Empty;public DateTime GrantedUtc{get;private set;}public DateTime?ExpiresUtc{get;private set;}public DateTime?WithdrawnUtc{get;private set;}public string ConsentVersion{get;private set;}=string.Empty;public long CapturedByUserId{get;private set;}public string?EvidenceReference{get;private set;}public DateTime CreatedUtc{get;private set;}
    public static CustomerRecognitionConsent Grant(long tenantId,long customerId,RecognitionConsentType consentType,string purpose,DateTime grantedUtc,DateTime?expiresUtc,string consentVersion,long capturedByUserId,string?evidenceReference)=>new(tenantId,customerId,consentType,purpose,grantedUtc,expiresUtc,consentVersion,capturedByUserId,evidenceReference);
    public bool IsActiveAt(DateTime utcNow)=>WithdrawnUtc is null&&GrantedUtc<=Utc(utcNow)&&(!ExpiresUtc.HasValue||ExpiresUtc>utcNow);
    public void Withdraw(DateTime utcNow){if(WithdrawnUtc.HasValue)throw new InvalidOperationException("Consent is already withdrawn.");var now=Utc(utcNow);if(now<GrantedUtc)throw new ArgumentOutOfRangeException(nameof(utcNow));WithdrawnUtc=now;}
    private static string Required(string value,int max){ArgumentException.ThrowIfNullOrWhiteSpace(value);var normalized=value.Trim();return normalized.Length<=max?normalized:throw new ArgumentOutOfRangeException(nameof(value));}
    private static string?Optional(string?value,int max)=>string.IsNullOrWhiteSpace(value)?null:Required(value,max);
    private static DateTime Utc(DateTime value)=>value.Kind==DateTimeKind.Utc?value:throw new ArgumentException("Timestamp must be UTC.",nameof(value));
}

