    public void DisableAndErase(DateTime utcNow,DateTime retentionUntilUtc){var now=Utc(utcNow);var retention=Utc(retentionUntilUtc);if(retention<now)throw new ArgumentOutOfRangeException(nameof(retentionUntilUtc));Status=BiometricTemplateStatus.Deleted;DisabledUtc??=now;DeletedUtc=now;RetentionUntilUtc=retention;EncryptedTemplate=[];Nonce=[];AuthenticationTag=[];}
