/// <summary>Reviewable match candidate; creation never changes the authoritative track/customer association.</summary>
public sealed class RecognitionCandidate
{
    private RecognitionCandidate(){}
    private RecognitionCandidate(long tenantId,long storeId,long personTrackSessionId,long biometricTemplateId,long customerId,string requestId,string purpose,decimal confidence,decimal quality,decimal?secondBestConfidence,RecognitionCandidateStatus status,string?reviewReason,DateTime createdUtc)
    {ArgumentOutOfRangeException.ThrowIfNegativeOrZero(tenantId);ArgumentOutOfRangeException.ThrowIfNegativeOrZero(storeId);ArgumentOutOfRangeException.ThrowIfNegativeOrZero(personTrackSessionId);ArgumentOutOfRangeException.ThrowIfNegativeOrZero(biometricTemplateId);ArgumentOutOfRangeException.ThrowIfNegativeOrZero(customerId);ValidateScore(confidence,nameof(confidence));ValidateScore(quality,nameof(quality));if(secondBestConfidence.HasValue)ValidateScore(secondBestConfidence.Value,nameof(secondBestConfidence));if(status is not(RecognitionCandidateStatus.PendingReview or RecognitionCandidateStatus.Ambiguous))throw new ArgumentOutOfRangeException(nameof(status));TenantId=tenantId;StoreId=storeId;PersonTrackSessionId=personTrackSessionId;BiometricTemplateId=biometricTemplateId;CustomerId=customerId;RequestId=Required(requestId,150);Purpose=Required(purpose,200);Confidence=confidence;Quality=quality;SecondBestConfidence=secondBestConfidence;Status=status;ReviewReason=Optional(reviewReason,500);CreatedUtc=Utc(createdUtc);}
