    public static RecognitionCandidate Create(long tenantId,long storeId,long personTrackSessionId,long biometricTemplateId,long customerId,string requestId,string purpose,decimal confidence,decimal quality,decimal?secondBestConfidence,RecognitionCandidateStatus status,string?reviewReason,DateTime createdUtc)=>new(tenantId,storeId,personTrackSessionId,biometricTemplateId,customerId,requestId,purpose,confidence,quality,secondBestConfidence,status,reviewReason,createdUtc);
    public void Review(bool accept,long reviewedByUserId,string reason,DateTime utcNow){ArgumentOutOfRangeException.ThrowIfNegativeOrZero(reviewedByUserId);if(Status is not(RecognitionCandidateStatus.PendingReview or RecognitionCandidateStatus.Ambiguous))throw new InvalidOperationException("Candidate is no longer awaiting review.");Status=accept?RecognitionCandidateStatus.Accepted:RecognitionCandidateStatus.Rejected;ReviewedByUserId=reviewedByUserId;ReviewReason=Required(reason,500);ReviewedUtc=Utc(utcNow);}
