    private static string Required(string value,int max){ArgumentException.ThrowIfNullOrWhiteSpace(value);var normalized=value.Trim();return normalized.Length<=max?normalized:throw new ArgumentOutOfRangeException(nameof(value));}
    private static string?Optional(string?value,int max)=>string.IsNullOrWhiteSpace(value)?null:Required(value,max);
